exact_tag_scans.command:
sh -c python3 -c 'import glob,json,os,signal,sys,time
tag=sys.argv[1].encode()
def owned():
 rows=[]
 for path in glob.glob("/proc/[0-9]*/environ"):
  try:
   if tag in open(path,"rb").read():
    rows.append(int(path.split("/")[2]))
  except OSError:
   pass
 return sorted(set(rows))
initial=owned()
for pid in initial:
 try: os.kill(pid,signal.SIGTERM)
 except (ProcessLookupError,PermissionError): pass
time.sleep(5)
forced=owned()
for pid in forced:
 try: os.kill(pid,signal.SIGKILL)
 except (ProcessLookupError,PermissionError): pass
time.sleep(1)
print(json.dumps({
 "initial":initial,
 "sigkill":forced,
 "final":owned(),
},sort_keys=True))
' 20260901-qwen38-tp4-decode-replay-r25-full

